def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color):
                    continue
                for sr, sc in ((-dr, -dc), (dr, dc)):
                    rr, cc = (r, c) if (sr, sc) == (-dr, -dc) else (nr, nc)
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] in (bg, color):
                        if out[rr][cc] == bg:
                            out[rr][cc] = color
                        rr += sr
                        cc += sc
    return out
